'use strict';
const assert=require('assert');
const fs=require('fs');
const path=require('path');
const root=path.resolve(__dirname,'..');
const html=fs.readFileSync(path.join(root,'index.html'),'utf8');
const css=fs.readFileSync(path.join(root,'styles.css'),'utf8');
const app=fs.readFileSync(path.join(root,'app.js'),'utf8');
const sw=fs.readFileSync(path.join(root,'service-worker.js'),'utf8');
const nav=html.match(/<nav class="admin-nav"[\s\S]*?<\/nav>/)?.[0]||'';
assert(nav,'admin navigation missing');
assert(!/Coming soon/i.test(nav),'Coming soon must not appear in the top menu');
assert(!/nav-coming-soon/.test(nav),'top menu must not contain coming-soon badge markup');
assert((nav.match(/data-view=/g)||[]).length===10,'top menu must contain exactly ten primary tabs');
assert(nav.includes('Opportunities &amp; Quotes'),'long opportunity label missing');
assert(html.includes('Marketing — Coming soon'),'Marketing page must retain its in-page status');
assert(html.includes('Mileage — Coming soon'),'Mileage page must retain its in-page status');
assert(css.includes('v56.0.1 — top-menu cleanup'),'top-menu cleanup CSS marker missing');
assert(css.includes('minmax(160px,1.55fr)'),'long Opportunities & Quotes tab must receive extra width');
assert(app.includes("marketing?.removeAttribute('title')"),'old Coming soon nav tooltip must be removed');
assert(sw.includes('tuinbooks-shell-v56-0-5-schedule-card-format1'),'service-worker cache token is stale');
console.log('v56.0.1 top-menu cleanup static tests passed');
